using System;using System.IO;using System.Reflection;using UnityEngine;using Bokumyaku.Presentation;
public static class ProjectionCheck{public static object Run(){var g=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();if(!g.SavePath.Contains("ink-qa-"))throw new Exception("Isolated only");var f=BindingFlags.Instance|BindingFlags.NonPublic;var w=typeof(BokumyakuGame).GetField("battleWorld",f).GetValue(g);var type=w.GetType();var method=type.GetMethod("Project",f);float max=0;int samples=0;foreach(float x in new[]{-300f,0f,300f})foreach(float y in new[]{-300f,-1f,0f,1f,300f}){var projected=(Vector2)method.Invoke(w,new object[]{new Vector2(x,y)});var sprite=(SpriteRenderer)type.GetField(y>=0?"upperInk":"lowerInk",f).GetValue(w);float u=(192+x*.48f)/384;float v=(256+y*.48f)/256-(y>=0?1:0);var bounds=sprite.sprite.bounds;var local=sprite.transform.localPosition+Vector3.Scale(new Vector3((u-.5f)*bounds.size.x,(v-.5f)*bounds.size.y),sprite.transform.localScale);max=Mathf.Max(max,Vector2.Distance(projected,local));samples++;}if(max>.0001f)throw new Exception("Ink projection misaligned: "+max);var result=new{passed=true,samples,maxWorldError=max};File.WriteAllText(Path.GetFullPath("../docs/evidence/ink-projection-check.json"),Newtonsoft.Json.JsonConvert.SerializeObject(result));return result;}}
